    timestamps="`observation_date` business DATE; detection timestamps UTC.",
    jsonb_note="`reasons`: array of `AnomalyReason {code, value?, threshold?}`; Pydantic `AnomalyReason`.",
    access="Upsert by natural key; list by product/date; list open by severity.",
    mutability="Identity (product, date, type, method, first_detected_at) immutable; measurements/status update in place on re-detection.",
    retention="24 months (dismissed/confirmed rows double as evaluation labels).",
