risk_assessment = Table(
    schema="intel", name="risk_assessment", cls="RiskAssessment", tier="H", scope="MVP",
    purpose="Deterministic risk result per product and risk type (stockout_risk, unusual_demand) with the exact inputs and rule version used. Versions are kept: a changed outcome inserts a new row and supersedes the old one, so recommendations keep pointing at the calculation they were based on.",
    cols=[ID(), TENANT(),
          col("product_id", "UUID", "Canonical product id."),
          col("supplier_id", "UUID", "Canonical supplier id whose lead time was used (external; see OD-04).", null=True),
          col("risk_type", "TEXT", "stockout_risk | unusual_demand."),
          col("severity", "TEXT", "low | medium | high."),
          col("confidence", "NUMERIC(4,3)", "0..1 where meaningful (stockout_risk); NULL for unusual_demand.", null=True),
          col("input_available_quantity", "NUMERIC(14,3)", "INPUT SNAPSHOT of ERP available_quantity used in the calculation. Provenance, not an inventory copy.", null=True),
          col("inventory_as_of", "TIMESTAMPTZ", "Time the inventory value was read from Canonical.", null=True),
          col("inventory_source", "TEXT", "canonical_live | canonical_cache.", null=True),
          col("demand_per_day", "NUMERIC(14,4)", "Forecast demand per day used.", null=True),
          col("demand_over_lead_time", "NUMERIC(14,3)", "Sum of forecast points over the supplier lead time.", null=True),
          col("demand_over_lead_time_upper", "NUMERIC(14,3)", "Conservative upper estimate (sum of daily confidence_high).", null=True),
          col("days_of_cover", "NUMERIC(8,2)", "available / demand_per_day.", null=True),
          col("lead_time_days", "NUMERIC(6,2)", "Supplier lead time used.", null=True),
          col("supplier_as_of", "TIMESTAMPTZ", "synced_at of the supplier payload used.", null=True),
          col("forecast_id", "UUID", "Forecast used.", null=True),
          col("anomaly_event_id", "UUID", "Driving anomaly (required for unusual_demand; optional escalation source for stockout_risk).", null=True),
          col("rule_version", "TEXT", "Rule set label used."),
          col("rule_config_id", "UUID", "Exact parameter set used."),
          col("calculation", "JSONB", "Rule trace: [{rule, matched, inputs, output}], other anomaly ids, notes.", default=EJ, jsonb="object"),
          col("calculated_at", "TIMESTAMPTZ", "When this version was first calculated (UTC).", default="now()"),
          col("last_confirmed_at", "TIMESTAMPTZ", "Last recalculation that produced the same outcome (heartbeat, avoids row churn).", default="now()"),
          col("superseded_at", "TIMESTAMPTZ", "Set when a newer version replaces this one.", null=True),
          col("superseded_by_id", "UUID", "The newer version.", null=True),
          TRACE()],
    pk=["id"], fk_target=True,
    fks=[tfk("fk_risk_assessment__forecast", "forecast_id", "intel.forecast", rel="forecast"),
         tfk("fk_risk_assessment__anomaly_event", "anomaly_event_id", "intel.anomaly_event", rel="anomaly_event"),
         tfk("fk_risk_assessment__rule_config", "rule_config_id", "intel.rule_config"),
         tfk("fk_risk_assessment__superseded_by", "superseded_by_id", "intel.risk_assessment", note="self reference")],
    checks=[("ck_risk_assessment__type", "risk_type IN ('stockout_risk','unusual_demand')"),
            ("ck_risk_assessment__severity", "severity IN ('low','medium','high')"),
            ("ck_risk_assessment__confidence", "confidence IS NULL OR confidence BETWEEN 0 AND 1"),
            ("ck_risk_assessment__inventory_source", "inventory_source IS NULL OR inventory_source IN ('canonical_live','canonical_cache')"),
            ("ck_risk_assessment__numbers_nonneg", "(demand_per_day IS NULL OR demand_per_day >= 0) AND (demand_over_lead_time IS NULL OR demand_over_lead_time >= 0) AND (days_of_cover IS NULL OR days_of_cover >= 0) AND (lead_time_days IS NULL OR lead_time_days >= 0)"),
            ("ck_risk_assessment__stockout_inputs", "risk_type <> 'stockout_risk' OR (days_of_cover IS NOT NULL AND lead_time_days IS NOT NULL AND input_available_quantity IS NOT NULL AND inventory_as_of IS NOT NULL)"),
            ("ck_risk_assessment__unusual_anomaly", "risk_type <> 'unusual_demand' OR anomaly_event_id IS NOT NULL"),
            ("ck_risk_assessment__supersede_pair", "(superseded_at IS NULL) = (superseded_by_id IS NULL)")],
    idxs=[Idx("uq_risk_assessment__current", ["tenant_id", "product_id", "risk_type"], unique=True, where="superseded_at IS NULL", why="Exactly one current assessment per product and risk type."),
          Idx("ix_risk_assessment__current_severity", ["tenant_id", "severity", "calculated_at"], where="superseded_at IS NULL", why="Dashboard: current at-risk products by severity."),
          Idx("ix_risk_assessment__product_history", ["tenant_id", "product_id", "calculated_at"], why="Risk history per product.")],
    guard_mutable=["last_confirmed_at", "superseded_at", "superseded_by_id"], grants="SIU", worker_grants="SIU", purge=True,
    writer="Risk engine (Ibrahim).",
    readers="Recommendation engine, `get_insight` tool, InsightCard API, agent proposals (as `insight_id`).",
    tenancy=TENANCY_STD,
    timestamps="All UTC. `calculated_at` = first calculation of this version; `last_confirmed_at` = heartbeat.",
    jsonb_note="`calculation`: object `RiskCalculation {rules[], anomaly_event_ids[], notes[]}`; Pydantic `RiskCalculation`. Typed columns hold every number the rule used so queries never need the JSON.",
    access="Current row by (tenant, product, risk_type); current list by severity; history per product.",
    mutability="Inputs/outcome immutable. Only last_confirmed_at and supersession fields change (guard trigger).",
    retention="13 months, but rows referenced by recommendations/proposals are kept (FK RESTRICT).",
    recovery="Recomputable from forecast + Canonical; history is kept because recommendations and approvals reference it.",
    migration="Depends on forecast, anomaly_event, rule_config. Self FK added with ALTER TABLE.",
    example={"tenant_id": T, "product_id": AMOX, "supplier_id": SUP, "risk_type": "stockout_risk", "severity": "high", "confidence": 0.72, "input_available_quantity": 40, "inventory_as_of": "2026-09-24T10:16:42Z", "inventory_source": "canonical_live", "demand_per_day": 24, "demand_over_lead_time": 120, "demand_over_lead_time_upper": 145, "days_of_cover": 1.67, "lead_time_days": 5, "rule_version": "risk-rules@1.0.0", "calculation": {"rules": [{"rule": "cover_lt_lead_time", "matched": True}]}})

recommendation = Table(
    schema="intel", name="recommendation", cls="Recommendation", tier="H", scope="MVP",
    purpose="Deterministic, structured suggestion derived from a risk (e.g. order 100 units from supplier X). Separate from any ERP transaction: a recommendation is never an executed purchase order.",
    cols=[ID(), TENANT(),
          col("product_id", "UUID", "Canonical product id."),
          col("supplier_id", "UUID", "Suggested supplier (external reference).", null=True),
          col("risk_assessment_id", "UUID", "Risk this recommendation answers (the source `risk_id`)."),
          col("forecast_id", "UUID", "Forecast used.", null=True),
          col("recommendation_type", "TEXT", "create_purchase_order | review_anomaly."),
          col("payload", "JSONB", "Structured payload. For create_purchase_order it mirrors the tool input_schema {supplier_id, lines[{product_id, quantity}]} so the agent copies it into the ActionProposal unchanged.", jsonb="object"),
          col("calculation", "JSONB", "Formula inputs and constraints checked: demand_over_lead, safety_stock, available, order_qty, bound_used, open-PO check status.", default=EJ, jsonb="object"),
          col("status", "TEXT", "active | dismissed | superseded | expired. ('actioned' is derived from agent.action_proposal, not stored.)", default="'active'"),
          col("generated_at", "TIMESTAMPTZ", "Generation time (UTC).", default="now()"),
          col("expires_at", "TIMESTAMPTZ", "After this time the recommendation is no longer offered."),
          col("superseded_at", "TIMESTAMPTZ", "When replaced by a newer recommendation.", null=True),
          col("superseded_by_id", "UUID", "Replacement recommendation.", null=True),
          col("rule_version", "TEXT", "Rule set label used."),
          col("rule_config_id", "UUID", "Exact parameter set used."),
          ROWV(), TRACE(), CREATED(), UPDATED()],
    pk=["id"], fk_target=True,
    fks=[tfk("fk_recommendation__risk_assessment", "risk_assessment_id", "intel.risk_assessment", rel="risk_assessment", back="recommendations"),
         tfk("fk_recommendation__forecast", "forecast_id", "intel.forecast", rel="forecast"),
         tfk("fk_recommendation__rule_config", "rule_config_id", "intel.rule_config"),
         tfk("fk_recommendation__superseded_by", "superseded_by_id", "intel.recommendation", note="self reference")],
    checks=[("ck_recommendation__type", "recommendation_type IN ('create_purchase_order','review_anomaly')"),
            ("ck_recommendation__status", "status IN ('active','dismissed','superseded','expired')"),
            ("ck_recommendation__expiry", "expires_at > generated_at"),
            ("ck_recommendation__supersede", "(status = 'superseded') = (superseded_at IS NOT NULL AND superseded_by_id IS NOT NULL)")],
    idxs=[Idx("uq_recommendation__active", ["tenant_id", "product_id", "recommendation_type"], unique=True, where="status = 'active'", why="At most one active recommendation per product and type; new one supersedes in the same transaction."),
          Idx("ix_recommendation__tenant_product_generated", ["tenant_id", "product_id", "generated_at"], why="History per product."),
          Idx("ix_recommendation__tenant_risk", ["tenant_id", "risk_assessment_id"], why="FK support; recommendations of a risk.")],
    updated_at_trigger=True,
    guard_mutable=["status", "superseded_at", "superseded_by_id", "expires_at", "row_version", "updated_at"],
    grants="SIU", worker_grants="SIU", purge=True,
    writer="Recommendation engine (Ibrahim).",
    readers="InsightCard API, `get_insight` tool, agent (builds ActionProposal), BI.",
    tenancy=TENANCY_STD,
    timestamps="UTC.",
    jsonb_note="`payload`: Pydantic `PurchaseOrderRecommendationPayload` (identical field names/types to the `create_purchase_order` tool schema) or `ReviewAnomalyPayload`. `calculation`: `RecommendationCalculation`.",
    access="Active row by (tenant, product, type); history by product; by risk id.",
    mutability="Content immutable; lifecycle fields (status, supersession, expiry) mutable via guarded UPDATE with `row_version` check.",
    retention="13 months; rows referenced by action proposals are kept (FK RESTRICT).",
    recovery="Re-generated from risk + forecast; history kept for provenance.",
    migration="Depends on risk_assessment, forecast, rule_config.",
    example={"tenant_id": T, "product_id": AMOX, "supplier_id": SUP, "recommendation_type": "create_purchase_order", "payload": {"supplier_id": SUP, "lines": [{"product_id": AMOX, "quantity": 100}]}, "calculation": {"demand_over_lead": 120, "safety_stock": 20, "available": 40, "order_qty": 100, "bound_used": "median", "open_po_check": "skipped_no_capability"}, "status": "active", "generated_at": "2026-09-24T10:16:45Z", "expires_at": "2026-09-25T10:16:45Z", "rule_version": "recommendation-rules@1.0.0"})

